// 渲染民族列表
function renderEthnicList() {
	const ethnicListDiv = document.getElementById('ethnicList');
	if (!ethnicListDiv) return;

	ethnicListDiv.innerHTML = allEthnicGroups.map(name => `
    `).join('');
}

// 渲染人口列表
function renderTopEthnicList() {
	const container = document.getElementById('topEthnicList');
	if (!container) return;

	container.innerHTML = topEthnicList.map(item => `
        <div class="ethnic-item">
            <div class="ethnic-name">
                <span class="ethnic-dot" style="background: var(--accent);"></span>
                ${item.name}
            </div>
            <div class="ethnic-pop">${item.population}</div>
        </div>
    `).join('');
}

// 初始化地图
function initMap() {

	svg.innerHTML = chinaMapData;

	svg.innerHTML = chinaMapData;
	const paths = svg.querySelectorAll('path');
	console.log(`✅ 加载了 ${paths.length} 个省份路径`);

	paths.forEach(path => {
		const provinceName = path.getAttribute('data-name');

		// 设置基础样式
		path.setAttribute('fill', 'rgba(66, 133, 244, 0.08)');
		path.setAttribute('stroke', 'rgba(66, 133, 244, 0.35)');
		path.setAttribute('stroke-width', '0.5');

		if (provinceName) {
			path.addEventListener('mouseenter', function(e) {
				this.setAttribute('fill', 'rgba(66, 133, 244, 0.25)');
				this.setAttribute('stroke', 'rgba(66, 133, 244, 0.8)');
				this.setAttribute('stroke-width', '1.5');
				showProvinceHoverCard(provinceName, e);
			});

			path.addEventListener('mousemove', function(e) {
				updateHoverCardPosition(e);
			});

			path.addEventListener('mouseleave', function() {
				this.setAttribute('fill', 'rgba(66, 133, 244, 0.08)');
				this.setAttribute('stroke', 'rgba(66, 133, 244, 0.35)');
				this.setAttribute('stroke-width', '0.5');
				hideProvinceHoverCard();
			});

			path.addEventListener('click', function(e) {
				e.stopPropagation();
				showProvinceDetail(provinceName);
			});
		}
	});
}

