// 显示省份悬停卡片
function showProvinceHoverCard(provinceName, event) {
	const hoverCard = document.getElementById('mapHoverCard');
	const data = provinceData[provinceName];

	if (!data || !hoverCard) return;

	// 获取卡片内的各个元素
	const provinceNameEl = document.getElementById('hoverProvinceName');
	const regionBadgeEl = document.getElementById('hoverRegionBadge');
	const projectsEl = document.getElementById('hoverProjects');
	const populationEl = document.getElementById('hoverPopulation');
	const progressEl = document.getElementById('hoverProgress');
	const ethnicEl = document.getElementById('hoverEthnic');

	// 设置内容
	provinceNameEl.textContent = provinceName;
	regionBadgeEl.textContent = data.region;
	regionBadgeEl.style.background = `${regionColors[data.region] || '#4285f4'}20`;
	regionBadgeEl.style.color = regionColors[data.region] || '#4285f4';

	// 设置面积
	projectsEl.textContent = data.area || '--';

	// 设置人口
	populationEl.textContent = data.population || '--';

	// 设置聚居地分布
	progressEl.textContent = data.distribution || '多民族散居';

	// 设置民族构成
	ethnicEl.textContent = data.ethnic || '多民族聚居';

	hoverCard.classList.add('show');
	updateHoverCardPosition(event);
}

// 更新悬停卡片位置
function updateHoverCardPosition(event) {
	const hoverCard = document.getElementById('mapHoverCard');
	if (!hoverCard.classList.contains('show')) return;

	const offsetX = 20;
	const offsetY = 20;
	const cardWidth = 280;
	const cardHeight = 240;

	let left = event.clientX + offsetX;
	let top = event.clientY + offsetY;

	if (left + cardWidth > window.innerWidth) {
		left = event.clientX - cardWidth - offsetX;
	}
	if (top + cardHeight > window.innerHeight) {
		top = event.clientY - cardHeight - offsetY;
	}
	if (left < 0) left = offsetX;
	if (top < 0) top = offsetY;

	hoverCard.style.left = left + 'px';
	hoverCard.style.top = top + 'px';
}

// 隐藏悬停卡片
function hideProvinceHoverCard() {
	const hoverCard = document.getElementById('mapHoverCard');
	hoverCard.classList.remove('show');
}

// 显示省份详情（改为打开新页面）
function showProvinceDetail(provinceName) {
	// 点击省份，在新标签页打开对应详情页面
	window.open(`province-detail.html?province=${encodeURIComponent(provinceName)}`, "_blank");
}
