// ==================== 弹窗关闭 ====================
function initPopupClose() {
	const closeBtn = document.getElementById('popupCloseBtn');
	const popup = document.getElementById('locationPopup');

	if (closeBtn) {
		closeBtn.addEventListener('click', () => {
			popup.classList.remove('show');
		});
	}

	document.addEventListener('click', (e) => {
		if (popup.classList.contains('show') && !popup.contains(e.target)) {
			popup.classList.remove('show');
		}
	});
}

// ==================== 数字滚动动画 ====================
function animateNumber(element, start, end, duration) {
	const range = end - start;
	const increment = range / (duration / 16);
	let current = start;

	const timer = setInterval(() => {
		current += increment;
		if ((increment > 0 && current >= end) || (increment < 0 && current <= end)) {
			current = end;
			clearInterval(timer);
		}
		element.textContent = Math.floor(current).toLocaleString();
	}, 16);
}

function initNumberAnimations() {
	const numbers = document.querySelectorAll('.overview-value');
	numbers.forEach(num => {
		const text = num.textContent.replace(/[^0-9.]/g, '');
		const finalValue = parseFloat(text);
		if (!isNaN(finalValue) && finalValue > 0) {
			const originalText = num.textContent;
			num.textContent = '0';
			setTimeout(() => {
				animateNumber(num, 0, finalValue, 1500);
				setTimeout(() => {
					num.innerHTML =
						`${Math.floor(finalValue)}<span class="unit">${originalText.includes('个') ? '个' : originalText.includes('亿') ? '亿' : ''}</span>`;
				}, 1500);
			}, 500);
		}
	});
}

// ==================== 进入动画 ====================
function initAnimations() {
	const cards = document.querySelectorAll('.overview-card, .info-card, .cultural-card, .region-list');

	cards.forEach((card, index) => {
		card.style.opacity = '0';
		card.style.transform = 'translateY(20px)';

		setTimeout(() => {
			card.style.transition = 'all 0.6s cubic-bezier(0.4, 0, 0.2, 1)';
			card.style.opacity = '1';
			card.style.transform = 'translateY(0)';
		}, 100 * index);
	});

	const mapContainer = document.querySelector('.map-container');
	if (mapContainer) {
		mapContainer.style.opacity = '0';
		mapContainer.style.transform = 'scale(0.95)';

		setTimeout(() => {
			mapContainer.style.transition = 'all 0.8s cubic-bezier(0.4, 0, 0.2, 1)';
			mapContainer.style.opacity = '1';
			mapContainer.style.transform = 'scale(1)';
		}, 300);
	}
}

